// Each concept has a short response, a reasoning task and a combined extended response.
(() => {
  function add(topic, key, title, shortPrompt, shortPoints, reasoningPrompt, reasoningPoints) {
    const variants = [
      ['short','Foundation',shortPrompt,shortPoints],
      ['reason','Standard',reasoningPrompt,reasoningPoints],
      ['extended','Challenge',`${shortPrompt}\n\n${reasoningPrompt}`,[...shortPoints,...reasoningPoints]]
    ];
    for (const [part,level,prompt,steps] of variants) {
      QUESTIONS.push({id:`explain-${topic}-${key}-${part}`,topic,level,title,prompt,steps,type:'written',marks:steps.length,family:key,variant:part});
    }
  }
  add(0,'random','Random uncertainty','Describe random measurement error and its effect on repeated readings.',['Unpredictable variations cause readings to scatter about a central value.','Readings can be above or below that value.'],'Explain why repeating and averaging readings reduces random uncertainty but cannot guarantee an accurate result.',['Independent positive and negative deviations partly cancel in the mean.','A systematic offset remains in the average, so improved precision does not guarantee accuracy.']);
  add(0,'zero','Zero error','A micrometer reads +0.03 mm when closed. State the type of error and the correction to apply.',['This is a systematic zero error.','Subtract 0.03 mm from each reading.'],'Explain why taking more readings of a wire with this micrometer does not remove its zero error.',['Every reading is displaced in the same direction by the same offset.','Averaging retains the offset; the instrument must be zeroed or the readings corrected.']);
  add(0,'precision','Precision and accuracy','Distinguish precision from accuracy.',['Precision describes the closeness of repeated measurements to one another.','Accuracy describes closeness to the accepted or true value.'],'Measurements cluster tightly around a value above the accepted value. Explain what this suggests and how it could be investigated.',['The measurements are precise but suggest a systematic bias.','Check calibration against a reference and look for zero errors or a consistent flaw in the method.']);
  add(0,'resolution','Instrument resolution','Define instrument resolution and give one example for a digital balance.',['Resolution is the smallest change in the measured quantity that the instrument can distinguish.','A balance displaying to 0.01 g has a display resolution of 0.01 g.'],'Explain why display resolution is not necessarily the total uncertainty in a measurement.',['Calibration, drift and fluctuations can produce uncertainties larger than a display increment.','The method, such as loss of material or unstable readings, can add uncertainty as well.']);
  add(0,'percentage','Absolute and percentage uncertainty','Distinguish absolute uncertainty from percentage uncertainty.',['Absolute uncertainty is expressed in the same unit as the measured quantity.','Percentage uncertainty is absolute uncertainty divided by the measured value, multiplied by 100.'],'Explain why measuring a longer length can reduce percentage uncertainty when using the same ruler and method.',['The uncertainty in the end readings can remain approximately constant.','Dividing that uncertainty by a larger measured length gives a smaller percentage uncertainty.']);
  add(0,'powers','Uncertainty in powers','A radius is squared to calculate an area. State how the percentage uncertainty in radius contributes to that in area.',['The percentage uncertainty in radius is multiplied by two.','The constant pi contributes no measurement uncertainty.'],'Explain why a small fractional error in radius has approximately twice that fractional effect on circular area.',['Area is proportional to r squared, so replacing r by r(1+epsilon) changes area by a factor (1+epsilon) squared.','For small epsilon, epsilon squared is negligible and the fractional change is approximately 2 epsilon.']);
  add(0,'gradient','Best-fit gradients','Describe how to calculate a gradient reliably from a plotted best-fit straight line.',['Choose two well-separated points on the best-fit line, which need not be original data points.','Calculate change in the vertical coordinate divided by change in the horizontal coordinate, including units.'],'Explain how uncertainty bars can be used to estimate uncertainty in a straight-line gradient.',['Draw steepest and shallowest lines that are consistent with the uncertainty bars.','Use half their gradient range as an estimate of absolute gradient uncertainty and compare with the best-fit gradient.']);
  add(0,'units','Dimensional checks','State the SI base units of force and energy.',['Force has base units kg m s^-2.','Energy has base units kg m squared s^-2.'],'Explain what a dimensional check can and cannot show about a proposed physics equation.',['Different dimensions on the two sides prove that the equation is inconsistent.','Matching dimensions do not establish numerical factors or prove that the physical model is valid.']);
  add(0,'anomaly','Anomalous results','Describe how a suspected anomalous reading should be investigated.',['Repeat the measurement under the same conditions and inspect the apparatus and recording procedure.','Do not remove a point solely because it does not fit the expected trend.'],'Explain why excluding a result needs a reason beyond obtaining a straighter graph.',['Random scatter can produce a genuine outlying result.','Selective removal biases the conclusion; a justified exclusion should identify an error or report evidence from repeat measurements.']);
  add(0,'figures','Significant figures','Explain why a calculated result should not normally retain every digit shown by a calculator.',['Input measurements have finite precision.','Extra calculator digits can imply a precision unsupported by the data.'],'Describe how to report a value with its absolute uncertainty consistently.',['Round the uncertainty appropriately, commonly to one or two significant figures.','Round the value to the same decimal place as the uncertainty and include units.']);
  add(1,'hadrons','Hadrons and leptons','Distinguish hadrons from leptons, giving an example of each.',['Hadrons consist of quarks and experience the strong interaction; a proton is an example.','Leptons do not experience the strong interaction; an electron is an example.'],'Explain the distinction between baryons and mesons in terms of quark structure.',['Baryons contain three quarks; antibaryons contain three antiquarks.','Mesons contain a quark and an antiquark, so their baryon number is zero.']);
  add(1,'antiparticles','Antiparticles','Compare the mass and electric charge of an electron and a positron.',['They have equal rest mass.','Their charges have equal magnitude and opposite sign.'],'Explain why electron-positron annihilation at rest cannot produce a single photon in otherwise empty space.',['The initial total momentum is zero, but a single photon necessarily has nonzero momentum.','Two photons can travel in opposite directions with equal momenta while conserving energy and momentum.']);
  add(1,'pair','Pair production','Describe photon pair production.',['A sufficiently energetic photon can produce a particle and its antiparticle.','The photon must supply at least the sum of their rest energies.'],'Explain why pair production commonly occurs near a nucleus and why energy above threshold is needed if the particles move.',['The nearby nucleus can take recoil momentum, allowing momentum conservation.','Any kinetic energy of the products and recoil must also come from the incident photon energy.']);
  add(1,'beta','Beta-minus decay','Describe the changes within a nucleus during beta-minus decay.',['A neutron changes into a proton, so proton number increases by one while nucleon number is unchanged.','An electron and an electron antineutrino are emitted.'],'Explain the role of the antineutrino in beta-minus decay.',['It carries some of the released energy and momentum, accounting for the continuous electron energy spectrum.','Its emission also conserves electron lepton number together with the emitted electron.']);
  add(1,'photoelectric','Photoelectric threshold','State what is meant by the threshold frequency of a metal.',['It is the minimum incident photon frequency that can cause photoelectric emission from that metal.','At threshold the maximum kinetic energy of emitted electrons is zero.'],'Explain why intense light below threshold fails to eject electrons in the usual single-photon photoelectric model.',['Each photon has energy hf below the work function.','Increasing intensity supplies more photons, not more energy per photon, so electrons cannot escape by absorbing one photon.']);
  add(1,'intensity','Intensity above threshold','For fixed frequency above threshold, state the effects of increasing light intensity on photoelectric emission.',['The rate of emitted electrons increases, provided collection and emission are not otherwise limited.','The maximum kinetic energy remains unchanged.'],'Explain these two effects using the photon model.',['Higher intensity at fixed frequency means a larger photon arrival rate.','Each photon still has the same energy hf, so hf minus the work function is unchanged.']);
  add(1,'lines','Atomic line spectra','Describe how an atom produces an emission line spectrum.',['Excited electrons move to lower allowed energy levels.','Each transition emits a photon with energy equal to the difference between the levels.'],'Explain why the spectrum has discrete lines and can identify an element.',['Only particular energy levels and energy differences are allowed, so only particular photon frequencies occur.','Different elements have different level structures and therefore characteristic sets of spectral lines.']);
  add(1,'excitation','Excitation and ionisation','Distinguish excitation from ionisation of an atom.',['Excitation raises an electron to a higher bound energy level.','Ionisation removes an electron completely from the atom.'],'Explain why an electron collision may excite an atom only when sufficient energy is transferred.',['The collision must supply the full energy difference between allowed levels.','Any remaining incident energy can remain as kinetic energy; the bound atom cannot retain an arbitrary intermediate excitation energy.']);
  add(1,'strong','The strong interaction','Describe the role and range of the strong interaction between nucleons.',['It binds nearby nucleons despite electrostatic repulsion between protons.','It is short ranged, acting over distances comparable with nuclear dimensions.'],'Explain why nuclei with many protons require neutrons for stability.',['Neutrons contribute attractive nuclear interactions without adding proton-proton electrostatic repulsion.','As nuclei grow, the long-range repulsion becomes more significant relative to the short-range attraction.']);
  add(1,'diffraction','Electron diffraction','State what electron diffraction demonstrates about electrons.',['Electrons exhibit wave behaviour.','Their associated wavelength is related to momentum by wavelength = h/p.'],'Explain how increasing the accelerating voltage affects electron diffraction angles in the non-relativistic regime.',['Higher accelerating voltage increases kinetic energy and momentum, reducing the de Broglie wavelength.','For a fixed crystal spacing, a smaller wavelength gives smaller diffraction angles for a given order.']);
  add(2,'transverse','Transverse and longitudinal waves','Distinguish transverse and longitudinal wave motion, with an example of each.',['Transverse oscillations are perpendicular to propagation, as for electromagnetic waves.','Longitudinal oscillations are parallel to propagation, as for sound in air.'],'Explain why polarisation demonstrates transverse rather than longitudinal wave motion.',['Polarisation selects a particular direction of oscillation perpendicular to propagation.','Longitudinal oscillations have no choice of transverse direction to select.']);
  add(2,'superposition','Superposition','State the principle of superposition for waves.',['When waves overlap, the resultant displacement is the algebraic sum of their individual displacements.','This applies at each point and instant in a linear medium.'],'Explain the conditions for complete destructive interference between two waves at a point.',['Their displacements must be in antiphase, corresponding to an odd half-wavelength path difference for initially in-phase sources.','Their amplitudes must be equal for the resultant amplitude to be zero.']);
  add(2,'coherence','Coherent sources','State what is meant by coherent wave sources.',['They have the same frequency.','They maintain a constant phase difference.'],'Explain why a stable double-slit interference pattern can be produced by illuminating both slits with one laser.',['Both slits are driven by the same incident wave, maintaining a fixed relative phase.','The phase difference at each screen position is then stable, giving stationary maxima and minima.']);
  add(2,'diffraction','Diffraction at a gap','Describe diffraction and when it is most noticeable at a gap.',['Diffraction is the spreading of a wave as it passes an aperture or edge.','Spreading is most noticeable when the aperture size is comparable to the wavelength.'],'Explain why sound spreads around a doorway much more noticeably than visible light.',['Sound wavelengths can be comparable to the doorway width.','Visible wavelengths are much smaller than the doorway, so the angular spreading is very small.']);
  add(2,'refraction','Refraction at a boundary','State what happens to frequency and wavelength when light enters glass from air.',['Frequency remains the same because the oscillations are driven at the source frequency.','Wavelength decreases because the wave speed decreases.'],'Explain why a ray bends towards the normal when it enters a slower medium obliquely.',['One part of the wavefront reaches the slower medium before another and slows first.','The wavefront changes direction, turning the propagation direction towards the normal.']);
  add(2,'tir','Total internal reflection','State the two conditions for total internal reflection.',['The light must travel from a higher refractive index medium towards a lower refractive index medium.','Its angle of incidence must exceed the critical angle.'],'Explain how the core and cladding of an optical fibre confine light.',['The core has a higher refractive index than the cladding.','Rays meeting the boundary above the critical angle undergo repeated total internal reflection and remain in the core.']);
  add(2,'stationary','Stationary waves','Describe how a stationary wave forms.',['Two waves of the same frequency and comparable amplitude travel in opposite directions and superpose.','Fixed nodes and antinodes result.'],'Explain the energy-transfer difference between an ideal stationary wave and a progressive wave.',['A progressive wave carries energy along its direction of propagation.','In an ideal stationary wave formed from equal opposite waves, the opposing energy flows cancel so there is no net transfer along the medium.']);
  add(2,'nodes','Nodes and antinodes','Distinguish a node from an antinode in a stationary wave.',['A node has zero displacement amplitude.','An antinode has maximum displacement amplitude.'],'Explain the phase relationships between points in a stationary wave.',['Points within one segment between adjacent nodes oscillate in phase.','Points in adjacent segments oscillate in antiphase; a node itself has no oscillation phase.']);
  add(2,'fringes','Double-slit spacing','State how double-slit fringe spacing changes when screen distance increases or slit separation increases.',['Increasing screen distance increases fringe spacing.','Increasing slit separation decreases fringe spacing.'],'Explain the condition that produces a bright fringe in a double-slit experiment with in-phase slits.',['The path difference must be an integer number of wavelengths.','The waves then arrive in phase and reinforce by constructive interference.']);
  add(2,'dispersion','Pulse broadening in fibres','Describe modal dispersion in a multimode optical fibre.',['Rays following different paths travel different distances through the fibre.','Their different arrival times broaden an initially short pulse.'],'Explain how pulse broadening limits data transmission and how a narrower core helps.',['Adjacent pulses can overlap, preventing the receiver from distinguishing separate bits.','A narrow or single-mode core reduces the range of allowed paths and therefore modal broadening.']);
  add(3,'newton','Newton third-law pairs','State two properties of a Newton third-law force pair.',['The forces have equal magnitude and opposite directions.','They act on different interacting bodies and are the same type of force.'],'Explain why the weight of a book and the normal force on that book are not a Newton third-law pair.',['Both forces act on the same body, the book.','The partner to the Earth pulling the book is the book pulling the Earth; the normal-force partner acts on the supporting surface.']);
  add(3,'terminal','Terminal speed','Describe the forces on an object falling through air at terminal speed.',['Its downward weight is balanced by upward drag, with buoyancy included if significant.','Its resultant force and acceleration are zero.'],'Explain how a falling object approaches terminal speed after release from rest.',['Initially drag is small, so weight produces downward acceleration.','As speed increases, drag increases and acceleration decreases until the forces balance.']);
  add(3,'momentum','Momentum conservation','State when the total momentum of a system is conserved.',['The resultant external force on the system must be zero, or its impulse negligible over the event.','Internal forces cannot change the total momentum of the complete system.'],'Explain why momentum can be conserved in an inelastic collision even though kinetic energy is not.',['The interacting bodies exert equal and opposite internal impulses, so their momentum changes cancel.','Some initial kinetic energy is transferred to internal energy, deformation and sound.']);
  add(3,'impulse','Cushioning an impact','Define impulse and give its relation to momentum.',['Impulse is the time integral of force, or average force multiplied by contact time.','It equals the change in momentum.'],'Explain why a crash mat reduces the average stopping force for the same landing speed.',['The momentum change needed to bring the person to rest is approximately unchanged.','The mat increases stopping time, so average force = momentum change / time is smaller.']);
  add(3,'projectile','Projectile independence','Describe the horizontal and vertical accelerations of an ideal projectile.',['Horizontal acceleration is zero when air resistance is neglected.','Vertical acceleration is g downwards, approximately constant near Earth.'],'Explain why two objects released simultaneously from the same height, one dropped and one launched horizontally, land together in the ideal model.',['They start with the same vertical velocity and undergo the same vertical acceleration.','Horizontal velocity does not affect the vertical motion, so the fall times are equal.']);
  add(3,'work','Work and force','Define work done by a constant force on a moving object.',['Work is the component of force along the displacement multiplied by the displacement.','Equivalently, W = Fs cos(theta), where theta is between force and displacement.'],'Explain why the centripetal force does no work in uniform circular motion.',['The force is perpendicular to the instantaneous displacement or velocity.','Its component along the motion is zero, so it changes direction rather than kinetic energy.']);
  add(3,'hooke','Elastic and plastic behaviour','Distinguish elastic and plastic deformation.',['Elastic deformation is recovered when the load is removed.','Plastic deformation leaves a permanent change in shape or length.'],'Explain why the limit of proportionality and the elastic limit need not be identical.',['The force-extension relation can become nonlinear while deformation is still reversible.','The elastic limit concerns permanent deformation, whereas proportionality concerns a straight-line relation through the origin.']);
  add(3,'young','Stress and strain','Define tensile stress and tensile strain.',['Tensile stress is force divided by the original cross-sectional area.','Tensile strain is extension divided by the original length.'],'Explain why Young modulus is more useful than spring stiffness for comparing different wire materials.',['Young modulus relates stress to strain, accounting for specimen area and length.','Stiffness F/extension depends on the specimen dimensions as well as the material.']);
  add(3,'moments','Equilibrium','State the two conditions for equilibrium of a rigid body.',['The resultant force is zero.','The resultant moment about any point is zero.'],'Explain why zero resultant force alone is insufficient for equilibrium.',['Equal opposite forces acting on different lines can form a couple.','A couple has zero resultant force but a nonzero moment that causes angular acceleration.']);
  add(3,'energy','Energy on a slope','Describe the energy changes when a trolley rolls down a frictionless slope from rest.',['Gravitational potential energy decreases.','Kinetic energy increases by the same amount if other energy transfers are negligible.'],'Explain why a real trolley may reach a lower speed than predicted by equating mgh with translational kinetic energy alone.',['Some energy may become rotational kinetic energy of the wheels.','Friction and air resistance can transfer energy to thermal stores and the surroundings.']);
  add(4,'current','Current and charge','Define electric current and state the direction of conventional current.',['Current is charge flow per unit time.','Conventional current is in the direction of positive charge flow, opposite to electron drift in a metal.'],'Explain why current is the same at every point in a steady series circuit.',['Charge is conserved.','A sustained difference in currents would cause charge to accumulate, contradicting a steady state.']);
  add(4,'potential','Potential difference and emf','Distinguish potential difference from emf using energy per unit charge.',['Potential difference is energy transferred per unit charge between two points.','Emf is energy supplied per unit charge by a source from another energy store.'],'Explain why a cell terminal voltage falls when the current supplied increases.',['Current also flows through the cell internal resistance.','The internal potential drop Ir increases, so terminal voltage = emf - Ir decreases.']);
  add(4,'metal','Metal resistance','Describe electrical conduction in a metal.',['Delocalised electrons move through a lattice of positive ions.','An electric field produces a net electron drift superimposed on random motion.'],'Explain why resistance usually increases as a metal temperature rises.',['The lattice ions vibrate more strongly.','More frequent electron scattering impedes drift, reducing current at a fixed potential difference.']);
  add(4,'ohm','Ohmic conductors','State Ohm law and its necessary physical condition.',['Current is directly proportional to potential difference.','Temperature and other relevant physical conditions must remain constant.'],'Explain why a filament lamp has a curved current-voltage characteristic.',['Increasing voltage increases heating and raises filament temperature.','The rising resistance means current increases less rapidly than voltage.']);
  add(4,'parallel','Parallel branches','State how potential difference and current behave in a parallel circuit.',['Each branch has the same potential difference between the common junctions.','The total current is the sum of the branch currents.'],'Explain why adding a resistor in parallel reduces the equivalent resistance.',['An extra conducting path draws additional current at the same applied voltage.','Since equivalent resistance is total voltage divided by total current, it decreases.']);
  add(4,'kirchhoff','Kirchhoff laws','State the junction and loop laws for a steady circuit.',['The total current entering a junction equals the total current leaving it.','Around a closed loop the algebraic sum of potential changes is zero.'],'Explain the conservation principles underlying these laws.',['The junction law follows from conservation of charge with no continuing accumulation.','The loop law follows from conservation of energy for charge completing a loop.']);
  add(4,'thermistor','Thermistor response','Describe the resistance change of an NTC thermistor as temperature increases.',['Its resistance decreases.','The response is nonlinear over a broad temperature range.'],'An NTC thermistor is the lower arm of a potential divider with a fixed upper resistor. Explain how its output voltage changes as it warms.',['Output across the thermistor is V_supply R_thermistor/(R_fixed + R_thermistor).','The thermistor resistance falls, so its fraction of the supply voltage and the output both fall.']);
  add(4,'ldr','Light-dependent resistors','Describe how an LDR responds to increasing illumination.',['Its resistance falls.','More charge carriers become available for conduction.'],'An LDR forms the upper arm of a divider with a fixed lower resistor. Explain what happens to voltage across the lower resistor in brighter light.',['The upper resistance decreases, so the total resistance falls and series current rises.','Voltage across the fixed lower resistor therefore rises.']);
  add(4,'resistivity','Wire dimensions','State how the resistance of a uniform wire depends on its length and cross-sectional area.',['At fixed material and temperature, resistance is proportional to length.','Resistance is inversely proportional to cross-sectional area.'],'Explain why wire temperature must be controlled when investigating resistance against length.',['Resistivity can change with temperature.','Changing temperature would introduce a second cause of resistance variation and obscure the effect of length.']);
  add(4,'meters','Ideal meter connections','State how to connect an ammeter and a voltmeter to measure a resistor current and voltage.',['Connect the ammeter in series with the resistor.','Connect the voltmeter in parallel across the resistor.'],'Explain the desirable resistances of these meters.',['An ammeter should have very low resistance to minimise the change to the series current.','A voltmeter should have very high resistance to draw negligible current and minimise loading.']);
  add(5,'internal','Internal energy','Describe the two microscopic contributions to internal energy.',['It includes the random kinetic energy of particles.','It includes potential energy associated with interactions between particles.'],'Explain why energy supplied during melting need not increase temperature.',['The energy changes particle arrangement and interaction potential energy.','Mean random kinetic energy, and hence temperature, remains approximately constant during the equilibrium phase change.']);
  add(5,'ideal','Ideal-gas assumptions','State two assumptions about particles in the kinetic model of an ideal gas.',['Particles have negligible volume compared with the container.','There are no intermolecular forces except during elastic collisions.'],'Explain microscopically why ideal-gas pressure increases with temperature at constant volume.',['Higher absolute temperature means greater mean molecular kinetic energy and speed.','Collisions with the walls transfer more momentum per unit time, producing a greater force per unit area.']);
  add(5,'absolute','Temperature and molecular energy','State the relationship between absolute temperature and mean molecular translational kinetic energy in an ideal gas.',['Mean translational kinetic energy is proportional to absolute temperature.','For each molecule the mean is 3kT/2.'],'Explain why two gases at the same temperature can have different root mean square molecular speeds.',['Their mean translational kinetic energies are equal.','Since kinetic energy depends on molecular mass times speed squared, lighter molecules have the larger rms speed.']);
  add(5,'shm','Defining SHM','State the acceleration condition for simple harmonic motion.',['Acceleration is proportional to displacement from equilibrium.','It is directed towards equilibrium: a = -omega squared x.'],'Explain why SHM speed is greatest at equilibrium and zero at the extremes.',['At equilibrium the oscillation energy is entirely kinetic in the ideal model.','At an extreme the object reverses direction and energy is stored as potential energy, so instantaneous speed is zero.']);
  add(5,'phase','SHM phase relationships','State where acceleration is zero and where its magnitude is greatest in SHM.',['Acceleration is zero at equilibrium.','Its magnitude is greatest at maximum displacement.'],'Explain the phase relationship between SHM displacement and acceleration.',['Acceleration is the negative constant multiple of displacement.','They are in antiphase, with positive displacement corresponding to negative acceleration.']);
  add(5,'resonance','Resonance','Describe resonance in a driven oscillator.',['A periodic driving force transfers energy to the oscillator.','A large steady oscillation amplitude occurs when driving frequency is near the natural frequency, especially with light damping.'],'Explain how increased damping changes the resonance response.',['More energy is dissipated each cycle, reducing the peak amplitude.','The resonance peak becomes less sharp, with a broader frequency response.']);
  add(5,'damping','Damped motion','Describe damping in an oscillator.',['Energy is transferred out of the oscillation, often to thermal stores.','The amplitude of free oscillations decreases with time.'],'Explain why critical damping is useful in a measuring instrument.',['The system returns to equilibrium as quickly as possible without oscillating.','This reduces settling time and avoids repeated overshoot of the final reading.']);
  add(5,'circular','Uniform circular motion','Explain why uniform circular motion involves acceleration.',['Speed is constant but velocity direction changes continuously.','Acceleration is directed towards the centre of the circle.'],'Explain why a centripetal force is not an additional type of force to add to a force diagram.',['Centripetal describes the inward resultant required for circular motion.','It is supplied by actual forces such as tension, gravity or friction, which should be identified individually.']);
  add(5,'thermal','Specific heat capacity','Define specific heat capacity.',['It is the energy required per unit mass for a unit temperature rise without a change of state.','Its SI unit is J kg^-1 K^-1.'],'Explain why ignoring heat losses in an electrical heating experiment can overestimate specific heat capacity.',['The calculation wrongly assumes all electrical energy Pt heats the sample.','Using an energy larger than the sample actually gains in c = E/(m delta T) produces too large a value.']);
  add(5,'pendulum','Pendulum assumptions','State two assumptions used in the small-angle simple-pendulum period formula.',['The oscillation angle is sufficiently small for sin(theta) to be approximately theta in radians.','The bob behaves as a point mass on a light inextensible support, with negligible damping.'],'Explain why increasing the bob mass does not change the ideal pendulum period.',['Both the gravitational restoring effect and the inertia are proportional to the mass.','The mass cancels from the motion equation, leaving T = 2 pi square root of (L/g).']);
  add(6,'fieldlines','Field lines','State how electric field lines represent direction and strength.',['Their direction is the force direction on a small positive test charge.','Closer spacing represents greater field strength in a consistent field-line drawing.'],'Explain why electrostatic field lines cannot cross.',['At a point the electric field has a single resultant direction.','A crossing would assign two different force directions to the same test charge at that point.']);
  add(6,'potential','Electric potential','Define electric potential at a point relative to infinity.',['It is work done per unit positive charge in bringing a small test charge from infinity to the point.','The test charge is moved without changing its kinetic energy.'],'Explain the relationship between electric field and equipotential surfaces.',['The field is perpendicular to an equipotential surface because no work is done moving along it.','The field points in the direction of decreasing potential; its component is the negative potential gradient.']);
  add(6,'gravity','Gravitational potential','Explain why gravitational potential around an isolated mass is negative when infinity is the zero.',['Gravity is attractive.','Energy must be supplied to move a unit mass from the point to infinity, so the point has lower potential.'],'Explain how gravitational field strength changes as distance from a spherical mass centre doubles outside the mass.',['Field strength is GM/r squared, so it becomes one quarter as large.','The field remains directed towards the mass centre.']);
  add(6,'orbit','Orbiting satellites','Describe the force responsible for a circular satellite orbit.',['Gravity supplies the inward resultant force.','It continuously changes the direction of the satellite velocity.'],'Explain why astronauts in an orbiting spacecraft appear weightless although gravity is present.',['The astronauts and spacecraft are in free fall with approximately the same acceleration.','Little or no support force acts on them, so their apparent weight is near zero.']);
  add(6,'capacitors','Charging a capacitor','Describe what happens to capacitor charge and charging current after connection through a resistor to a DC supply.',['Charge rises towards a limiting value CV_supply.','Charging current starts at its maximum and decreases towards zero.'],'Explain why the charging current decreases.',['The increasing capacitor voltage opposes the supply voltage in the charging loop.','The resistor voltage and hence I = V_resistor/R decrease.']);
  add(6,'timeconstant','RC time constant','State the significance of one time constant for a discharging capacitor.',['The time constant is RC.','After RC the charge and voltage are 1/e, about 37%, of their initial values.'],'Explain why doubling resistance slows capacitor discharge without changing the initial stored energy.',['A larger resistance reduces current for a given capacitor voltage and doubles RC.','Initial energy depends on C and initial V through CV squared/2, not on the discharge resistance.']);
  add(6,'magnetic','Magnetic force on a charge','State when a moving charged particle experiences zero magnetic force in a uniform field.',['There is no magnetic force when it is stationary.','There is also no force when its velocity is parallel or antiparallel to the field.'],'Explain why a magnetic field alone cannot increase the kinetic energy of a moving charged particle.',['The magnetic force is perpendicular to its instantaneous velocity.','No work is done by that force, so the speed and kinetic energy remain constant.']);
  add(6,'lenz','Lenz law','State Lenz law for electromagnetic induction.',['An induced emf drives a current whose magnetic effect opposes the change in flux that produces it.','The opposition concerns the change, not necessarily the original field itself.'],'Explain how Lenz law is consistent with conservation of energy when a magnet is pushed into a coil.',['The induced current produces a force resisting the approach.','External work is required, supplying the electrical energy or thermal energy produced in the circuit.']);
  add(6,'transformer','Transformer operation','Describe the roles of the primary and secondary coils in a transformer.',['An alternating primary current produces changing magnetic flux in the core.','Changing flux linkage induces an alternating emf in the secondary.'],'Explain why a transformer cannot provide a continuous secondary emf from a steady DC input.',['After the switching transient the primary flux is no longer changing.','Faraday law requires a change of flux linkage, so no continuous secondary emf is induced.']);
  add(6,'transmission','Power transmission','State the reason for transmitting a given electrical power at high voltage.',['Higher transmission voltage permits lower current for the same power.','Lower current reduces heating losses in the cables.'],'Explain why halving the transmission current reduces resistive power loss to a quarter.',['Cable heating power is I squared R.','With unchanged resistance, replacing I by I/2 gives I squared R/4.']);
  add(7,'random','Random radioactive decay','Explain the meaning of spontaneous and random radioactive decay.',['Spontaneous means the nucleus decays without an external trigger.','Random means the exact decay time of an individual nucleus cannot be predicted.'],'Explain why a large sample can show a predictable exponential decay curve despite random individual decays.',['Each surviving nucleus has the same constant probability of decay per unit time for a given isotope.','With many nuclei, fluctuations are small relative to the total and the mean rate is proportional to the number remaining.']);
  add(7,'halflife','Half-life and activity','Define half-life and activity.',['Half-life is the time for the number of undecayed nuclei, or activity, to fall to half its value.','Activity is the mean number of nuclear decays per unit time.'],'Explain why the activity of a pure sample falls as it ages while its decay constant stays the same.',['There are fewer undecayed nuclei available to decay.','The decay probability per surviving nucleus is unchanged, so A = lambda N falls because N falls.']);
  add(7,'penetration','Radiation penetration','Compare alpha and gamma radiation in terms of ionisation and penetration.',['Alpha radiation is strongly ionising and has short range.','Gamma radiation is less densely ionising and more penetrating.'],'Explain why an alpha emitter is especially hazardous inside the body but often much less hazardous outside intact skin.',['Alpha particles deposit energy densely in nearby tissue and can cause substantial local ionisation.','Their short range means external alpha particles are usually stopped by outer layers, but an internal source irradiates sensitive tissue directly.']);
  add(7,'background','Background radiation','Give two sources of background ionising radiation.',['Cosmic rays contribute background radiation.','Natural radionuclides in rocks, air or the body also contribute.'],'Explain how background should be accounted for when measuring source activity with a detector.',['Measure the background rate over a sufficiently long interval without the source.','Subtract that rate from the measured total rate; a detector count rate is not automatically the full source activity.']);
  add(7,'binding','Binding energy','Define nuclear binding energy.',['It is the energy required to separate a nucleus completely into individual free nucleons.','It equals the mass defect multiplied by c squared.'],'Explain why both fusion of light nuclei and fission of very heavy nuclei can release energy.',['Their products can have greater binding energy per nucleon.','The increase in total binding energy corresponds to a decrease in total rest mass, released as energy.']);
  add(7,'fission','Fission chain reactions','Describe a neutron-induced fission chain reaction.',['A nucleus absorbs a neutron and splits, releasing energy and more neutrons.','Some released neutrons cause further fissions.'],'Explain the separate roles of a moderator and control rods in a thermal nuclear reactor.',['The moderator slows neutrons by collisions, increasing the likelihood of suitable fuel nuclei undergoing fission.','Control rods absorb neutrons to regulate the number available to sustain the chain reaction.']);
  add(7,'fusion','Fusion conditions','State why fusion of light positively charged nuclei requires high temperatures.',['The nuclei repel electrostatically.','High kinetic energies increase the chance of approaching closely enough for the strong interaction to bind them.'],'Explain why confinement is also necessary for sustained fusion.',['The hot particles would otherwise escape or lose energy too quickly.','Sufficient density and confinement time are needed for enough fusion reactions to replace energy losses.']);
  add(7,'radius','Nuclear radius','State how nuclear radius depends approximately on nucleon number.',['Radius is proportional to the cube root of nucleon number.','The relation is R = r_0 A^(1/3), with approximately constant r_0.'],'Explain what this relation implies about nuclear density.',['Nuclear volume is proportional to R cubed and therefore to A.','Nuclear mass is also approximately proportional to A, so mass divided by volume is approximately constant.']);
  add(7,'scattering','Alpha scattering','Describe the key observation in alpha scattering that indicates a small dense nucleus.',['Most alpha particles pass through thin foil with little deflection.','A very small fraction undergo very large deflections or turn back.'],'Explain how these observations support the nuclear model of the atom.',['The frequent near-straight paths indicate that most atomic volume contains little concentrated mass or charge.','Large deflections require a concentrated positive charge and most of the mass in a tiny central region.']);
  add(7,'inverse','Inverse-square radiation','State the conditions for a point-source inverse-square intensity model.',['Emission should be isotropic from a source small compared with the distance.','Absorption and scattering between source and detector should be negligible.'],'Explain why measured radiation count rate may not follow a simple inverse-square law at short distances.',['The source or detector dimensions may no longer be small relative to their separation.','The detector solid angle then does not scale simply as fixed area divided by distance squared.']);
  add(8,'telescope','Refracting telescopes','Describe normal adjustment of an astronomical refracting telescope.',['The objective forms a real image at its focal plane.','That plane coincides with the eyepiece focal plane, so emerging rays are parallel and the final image is at infinity.'],'Explain why increasing objective diameter can improve a telescope independently of magnification.',['A larger objective collects more light, allowing fainter objects to be detected.','It reduces diffraction spreading and can improve angular resolution.']);
  add(8,'reflector','Reflecting telescopes','State two advantages of a reflecting telescope over a comparable simple refractor.',['A mirror does not produce chromatic aberration through wavelength-dependent refraction.','Large mirrors can be supported from behind, making large apertures practical.'],'Explain the origin of chromatic aberration in a simple refracting lens.',['The refractive index of the glass depends on wavelength.','Different colours are brought to different focal positions, producing coloured blurring.']);
  add(8,'resolution','Angular resolution','Describe what is meant by resolving two distant point sources.',['Their images can be distinguished as two separate sources.','Resolution is limited by diffraction even for an otherwise perfect optical instrument.'],'Explain why increasing magnification alone cannot resolve stars whose diffraction patterns overlap too strongly.',['Magnification enlarges the existing diffraction patterns as well as their separation.','It does not change the aperture-controlled angular resolution or restore lost detail.']);
  add(8,'temperature','Stellar colour','Describe how the peak emission wavelength of a black body changes with temperature.',['Peak wavelength decreases as temperature rises.','Wien law gives peak wavelength x temperature = constant.'],'Explain why a blue star can have a higher surface temperature than a red star.',['The hotter star emits relatively more strongly at shorter visible wavelengths.','The colour reflects the distribution across a broad spectrum, rather than emission at only a single wavelength.']);
  add(8,'luminosity','Luminosity and brightness','Distinguish stellar luminosity from received radiant flux.',['Luminosity is total emitted power.','Received radiant flux is power received per unit area at the observer.'],'Explain why two stars with equal observed brightness need not have equal luminosities.',['Received flux depends on both luminosity and distance through L/(4 pi d squared).','A more distant star can have the same observed flux if it is intrinsically more luminous.']);
  add(8,'magnitude','Stellar magnitudes','Distinguish apparent magnitude from absolute magnitude.',['Apparent magnitude describes observed brightness.','Absolute magnitude is the apparent magnitude the star would have at a distance of 10 parsecs.'],'Explain why comparing absolute magnitudes is more useful than apparent magnitudes for comparing intrinsic brightness.',['Absolute magnitude uses a common reference distance.','It removes the inverse-square distance effect that changes apparent brightness.']);
  add(8,'spectrum','Stellar absorption lines','Describe the origin of dark absorption lines in a stellar spectrum.',['Light from hotter layers passes through cooler gas.','Atoms absorb photons at particular energies corresponding to allowed transitions.'],'Explain how these lines can be used to measure radial motion.',['Compare identified line wavelengths with their laboratory rest wavelengths.','A systematic shift to longer wavelengths indicates recession; the fractional shift gives radial speed in the appropriate Doppler model.']);
  add(8,'hubble','Hubble law','State the approximate relationship between galaxy recession speed and distance in Hubble law.',['Recession speed is proportional to distance for the regime in which the relation is used.','The proportionality constant is H_0.'],'Explain why nearby galaxies need not follow a smooth Hubble relation exactly.',['Galaxies also have peculiar velocities due to local gravitational interactions.','At small distances these velocities can be comparable to or larger than the recession associated with expansion.']);
  add(8,'hr','The Hertzsprung-Russell diagram','State the quantities plotted on a Hertzsprung-Russell diagram and the usual temperature-axis direction.',['It plots luminosity or absolute magnitude against surface temperature or spectral class.','Temperature usually decreases from left to right.'],'Explain how a cool red giant can be more luminous than a hotter main-sequence star.',['Luminosity depends on emitting surface area as well as temperature, through L = 4 pi R squared sigma T to the fourth power.','A sufficiently large radius can more than compensate for a lower surface temperature.']);
  add(8,'supernova','Type Ia supernovae','Describe why Type Ia supernovae can serve as standardisable candles.',['Their peak luminosities can be estimated using calibrated relationships, including their light-curve properties.','Comparing estimated intrinsic luminosity with observed brightness gives a distance.'],'Explain one strength and one limitation of using supernovae to measure large distances.',['Their high luminosity makes them observable far beyond many individual stars.','Dust extinction or imperfect luminosity calibration can bias distance estimates and must be accounted for.']);
  add(9,'myopia','Correcting myopia','Describe myopia and the type of correcting lens used.',['Distant objects focus in front of the retina in the uncorrected eye.','A diverging lens with negative power is used.'],'Explain how a diverging lens allows a myopic eye to focus a distant object.',['It makes incoming parallel rays diverge as if from the eye far point.','The eye can then focus these rays on the retina.']);
  add(9,'ear','Sound detection','Describe how sound reaches the inner ear from the eardrum.',['Sound pressure variations vibrate the eardrum and middle-ear bones.','The bones transmit vibrations to the oval window and fluid in the cochlea.'],'Explain why sound intensity level is expressed on a logarithmic scale.',['The relevant intensities span many orders of magnitude.','A logarithmic scale expresses ratios compactly and better reflects relative perception than a linear intensity scale.']);
  add(9,'piezo','Piezoelectric ultrasound','Describe how a piezoelectric transducer generates ultrasound.',['An alternating voltage makes the crystal expand and contract.','These vibrations produce pressure waves at ultrasonic frequency.'],'Explain how the same type of transducer can detect returning echoes.',['An arriving pressure wave deforms the crystal.','The piezoelectric effect produces a changing voltage that can be measured.']);
  add(9,'gel','Ultrasound coupling','State the role of coupling gel in an ultrasound examination.',['It removes air gaps between probe and skin.','It allows a greater fraction of ultrasound energy to enter the body.'],'Explain why air gaps cause poor ultrasound transmission.',['Air and tissue have very different acoustic impedances.','The large impedance mismatch produces strong reflection at the boundary, leaving little transmitted energy.']);
  add(9,'scans','A-scans and B-scans','Distinguish an ultrasound A-scan from a B-scan.',['An A-scan displays echo amplitude against time or depth along one line.','A B-scan uses brightness to represent echo strength across multiple scan lines to form an image.'],'Explain why echo time must be halved when converting total travel time into depth using wave speed.',['The recorded delay includes travel from probe to boundary and back again.','For the same outward and return speed, each one-way journey occupies half the total time.']);
  add(9,'endoscope','Endoscope fibres','Distinguish coherent and non-coherent fibre bundles in an endoscope.',['A coherent bundle keeps the same relative fibre positions at both ends and transmits an image.','A non-coherent bundle can provide illumination without preserving image positions.'],'Explain how total internal reflection guides light through each fibre.',['The core has higher refractive index than the cladding.','Light incident above the critical angle at the core boundary is reflected back into the core.']);
  add(9,'xray','X-ray production','Describe the production of the continuous X-ray spectrum in a tube.',['Accelerated electrons strike the target and decelerate.','Different fractions of electron kinetic energy become photon energy, producing a continuous range.'],'Explain how increasing tube accelerating voltage changes the minimum X-ray wavelength.',['The maximum electron kinetic energy eV increases.','The maximum photon energy increases, so the minimum wavelength hc/(eV) decreases.']);
  add(9,'ct','CT images','Describe how a CT scanner obtains information for a cross-sectional image.',['X-ray transmission is measured through the body from many directions.','A computer reconstructs a map of attenuation within a slice.'],'Explain one advantage and one disadvantage of CT compared with a single projection X-ray image.',['Cross-sectional reconstruction reduces superposition of structures and can reveal internal detail more clearly.','Multiple X-ray exposures generally involve a higher ionising radiation dose than a single projection.']);
  add(9,'mr','Magnetic resonance imaging','Outline the signal production used in an MR scanner.',['A strong magnetic field establishes a net alignment of hydrogen nuclei; radiofrequency pulses excite them.','Radiofrequency signals from the nuclei are detected and processed into an image.'],'Explain the role of gradient fields and a radiation-related advantage of MR over CT.',['Gradient fields make resonance conditions position-dependent so signals can be located spatially.','MR uses magnetic fields and radio waves rather than ionising X-rays.']);
  add(9,'tracer','Radioactive tracers','State two desirable properties of a medical imaging tracer.',['It should emit radiation, commonly gamma rays, that can escape the body for external detection.','It should reach the target organ and have a suitable half-life for imaging while limiting prolonged exposure.'],'Explain why effective half-life in an organ is shorter than either physical or biological half-life alone.',['Radioactive decay removes radioactive nuclei and biological processes remove tracer independently.','The removal rates add, so the reciprocal effective half-life is the sum of the two reciprocal half-lives.']);
  add(10,'inertia','Rotational inertia','Define moment of inertia for a set of particles about a specified axis.',['It is the sum of each particle mass multiplied by the square of its perpendicular distance from the axis.','It measures resistance to angular acceleration about that axis.'],'Explain why moving mass away from a rotation axis increases moment of inertia.',['Each contribution is mr squared.','Increasing r increases that contribution even when total mass is unchanged.']);
  add(10,'torque','Torque and acceleration','State the rotational equivalent of Newton second law.',['Resultant torque equals moment of inertia times angular acceleration for a fixed axis and constant inertia.','The relation is torque = I alpha.'],'Explain why the same motor torque produces less angular acceleration when a heavier flywheel is fitted at the same radius.',['The flywheel moment of inertia increases.','From alpha = torque/I, a larger inertia gives a smaller angular acceleration for the same resultant torque.']);
  add(10,'angular','Angular momentum conservation','State the condition for conservation of total angular momentum.',['The resultant external torque about the chosen axis must be zero.','Internal torques can redistribute angular momentum but cannot change the total.'],'Explain why a rotating person speeds up when drawing their arms inward.',['Bringing mass closer to the axis reduces the moment of inertia.','With negligible external torque, I omega remains constant, so angular speed increases.']);
  add(10,'flywheel','Flywheel smoothing','Describe the energy store of a rotating flywheel.',['It stores rotational kinetic energy.','For a rigid flywheel this is I omega squared/2.'],'Explain how a flywheel smooths speed fluctuations in an engine.',['It gains energy when engine torque exceeds the resisting load torque.','It gives up energy when engine torque is smaller, reducing changes in rotational speed.']);
  add(10,'coupling','Coupled flywheels','State which quantity is conserved when rotating flywheels are coupled with no external torque.',['Total angular momentum is conserved.','Rotational kinetic energy need not be conserved.'],'Explain where energy goes during an initially slipping coupling.',['Friction transfers energy to thermal stores in the coupling and surrounding parts.','The flywheels can therefore settle at a common speed with less rotational kinetic energy.']);
  add(10,'firstlaw','Thermodynamic energy accounting','State the first law using work done by a gas as positive.',['Increase in internal energy = heat supplied - work done by the gas.','This is conservation of energy applied to the thermodynamic system.'],'Explain why an ideal gas cools during an adiabatic expansion that does work.',['No heat enters during an adiabatic process.','Work done by the gas reduces its internal energy and hence its temperature.']);
  add(10,'isothermal','Isothermal changes','State what remains constant in an isothermal change of an ideal gas.',['Temperature remains constant.','Internal energy of a fixed amount of ideal gas remains constant because it depends only on temperature.'],'Explain the heat transfer required during a slow isothermal expansion of an ideal gas.',['The gas does work on its surroundings.','An equal amount of heat must enter to keep internal energy and temperature constant.']);
  add(10,'pv','Pressure-volume diagrams','State what the area under a pressure-volume curve represents.',['It is work done by the gas during expansion, using W = integral p dV.','For compression the work done by the gas is negative.'],'Explain what the enclosed area of a clockwise pressure-volume cycle represents.',['Expansion work exceeds the magnitude of compression work.','The enclosed area is the positive net work output per cycle.']);
  add(10,'efficiency','Heat-engine efficiency','Define the thermal efficiency of a heat engine.',['Efficiency is useful net work output divided by heat input from the hot reservoir.','It may be expressed as a fraction or percentage.'],'Explain why a cyclic heat engine cannot convert all its heat input into useful work.',['A working engine must reject some heat to a colder reservoir in accordance with the second law.','For reversible operation the limiting efficiency is 1 - T_cold/T_hot, less than one for positive cold-reservoir temperature.']);
  add(10,'refrigerator','Refrigerators','Describe the energy transfers of a refrigerator.',['It extracts heat from a cold region and transfers heat to warmer surroundings.','External work is supplied to drive this transfer.'],'Explain why the heat rejected by a refrigerator exceeds the heat extracted from its cold compartment.',['Energy is conserved over a complete operating cycle.','Rejected heat equals extracted heat plus the work supplied to the refrigerator.']);
  add(11,'cathode','Cathode rays','State two observations supporting the interpretation of cathode rays as charged particles.',['They are deflected by electric and magnetic fields.','Their electric deflection indicates negative charge.'],'Explain how crossed electric and magnetic fields can select a particle speed.',['For undeflected motion the electric and magnetic forces oppose with equal magnitude: qE = qvB.','The selected speed is E/B, independent of charge magnitude.']);
  add(11,'millikan','Oil-drop charge','Describe the force balance on a stationary charged oil drop in a vertical electric field, neglecting buoyancy.',['The electric force acts upwards and balances the downward weight.','The magnitudes obey qE = mg.'],'Explain how measurements on many drops give evidence for charge quantisation.',['The inferred charges occur in approximately integer multiples of a common smallest value.','That common unit is the elementary charge, rather than a continuous distribution of arbitrary charges.']);
  add(11,'light','Wave and particle models of light','Give one observation supporting the wave model and one supporting the photon model of light.',['Interference or diffraction shows wave behaviour.','Photoelectric emission with a threshold frequency supports energy transfer in photons.'],'Explain why no single classical wave-only model accounts for all photoelectric observations.',['Energy transfer depends on photon frequency rather than only total light intensity.','A threshold and prompt single-photon emission above threshold are not explained by gradual accumulation of classical wave energy.']);
  add(11,'matter','Matter waves','State the de Broglie relation and the quantities it connects.',['Wavelength = h/p.','It relates the wavelength associated with a particle to its momentum.'],'Explain why wave behaviour is observable for electrons but normally unnoticeable for everyday moving objects.',['Everyday objects have much larger momenta and therefore extremely small de Broglie wavelengths.','Their wavelengths are far smaller than practical apertures or structures needed for observable diffraction.']);
  add(11,'electronmicroscope','Electron microscopes','State the principal reason an electron microscope can resolve smaller structures than a visible-light microscope.',['Accelerated electrons can have much shorter wavelengths than visible light.','A shorter wavelength reduces the diffraction-limited scale of detail.'],'Explain why increasing electron accelerating voltage can improve ideal diffraction-limited resolution.',['Higher kinetic energy increases electron momentum.','The de Broglie wavelength h/p decreases, reducing diffraction spreading for comparable geometry.']);
  add(11,'michelson','The Michelson-Morley result','Describe the result sought in the Michelson-Morley experiment and the outcome.',['An orientation-dependent interference shift was sought as evidence of motion through a proposed light-carrying ether.','No expected ether-wind shift was detected.'],'Explain how the null result relates to the development of special relativity.',['It undermined the proposed detectable preferred ether frame used in that model.','It is consistent with light speed being invariant in inertial frames, though the experiment alone is not a derivation of all relativity.']);
  add(11,'postulates','Special relativity postulates','State the two postulates of special relativity.',['The laws of physics have the same form in all inertial reference frames.','The speed of light in vacuum is the same for all inertial observers, independent of source motion.'],'Explain why a Galilean addition of observer speed to light speed conflicts with these postulates.',['Galilean velocity addition predicts different measured light speeds for observers moving relative to each other.','Invariant light speed requires different transformations of space and time between frames.']);
  add(11,'time','Proper time','Define proper time between two events.',['It is the time interval measured in a frame where both events occur at the same spatial position.','A single clock at that position can measure the interval.'],'Explain why a laboratory observer measures a longer lifetime for a fast-moving unstable particle than its proper lifetime.',['In the particle rest frame, creation and decay occur at the same position, defining proper lifetime.','The laboratory lifetime is gamma times the proper lifetime, with gamma greater than one.']);
  add(11,'length','Proper length','Define the proper length of an object.',['It is the length measured in the object rest frame.','The object is stationary relative to the measuring apparatus.'],'Explain how a moving rod length is measured in another frame and why simultaneous endpoint readings matter.',['The positions of both ends must be recorded at the same time in the observer frame.','Recording at different times includes motion of the rod and does not measure its length at one instant.']);
  add(11,'massenergy','Rest energy','State the relation between rest mass and rest energy.',['Rest energy is E_0 = mc squared.','An object can have rest energy even when its kinetic energy is zero.'],'Explain why the classical kinetic-energy formula becomes inaccurate for a particle travelling close to light speed.',['The classical formula is a low-speed approximation.','Relativistic kinetic energy is (gamma - 1)mc squared and grows without bound as speed approaches c for a particle with nonzero rest mass.']);
  add(12,'logic','Digital logic levels','Describe how a digital circuit represents binary 0 and 1 electrically.',['Two specified voltage ranges represent the two logic states.','A valid state need not be one exact voltage within its permitted range.'],'Explain why separated valid voltage ranges help digital signals tolerate small amounts of noise.',['A small disturbance can leave the signal inside the same valid logic range.','The receiver still assigns the same binary state, provided the noise margin is not exceeded.']);
  add(12,'gates','AND and OR gates','Distinguish the outputs of two-input AND and OR gates.',['AND gives 1 only when both inputs are 1.','OR gives 1 when either or both inputs are 1.'],'Explain how an AND gate can be used to require both a safety interlock and a start command.',['Represent each satisfied condition by logic 1.','The output becomes 1 only when both required conditions are present.']);
  add(12,'inverter','NOT and NAND gates','Describe NOT and NAND operations.',['NOT reverses a single binary input.','NAND is the inverse of AND and gives 0 only when all its inputs are 1.'],'Explain how a two-input NAND gate can be used as a NOT gate.',['Connect both inputs to the same signal.','Input 0 gives output 1 and input 1 gives output 0, reproducing inversion.']);
  add(12,'opamp','Ideal operational amplifiers','State two ideal operational-amplifier properties relevant to its inputs.',['Its input resistance is infinite, so no current enters either input.','Its open-loop voltage gain is infinite in the ideal model.'],'Explain why the two input voltages are approximately equal during linear operation with negative feedback.',['A finite output with very large open-loop gain requires a very small differential input voltage.','Negative feedback adjusts the output to reduce that difference, provided the amplifier is not saturated.']);
  add(12,'virtual','Virtual earth','Describe the virtual-earth point in an ideal inverting amplifier.',['Negative feedback holds the inverting input approximately at the grounded non-inverting input potential.','It is not physically connected to ground, despite being near zero volts.'],'Explain why input-resistor current flows through the feedback resistor in an ideal inverting amplifier.',['The ideal op-amp input draws no current.','Charge conservation at the inverting-input junction makes the input and feedback currents equal in magnitude.']);
  add(12,'clipping','Amplifier clipping','Describe output clipping in an amplifier.',['The output cannot exceed its available output voltage limits.','Portions of the desired waveform beyond these limits become flattened.'],'Explain how reducing input amplitude can remove clipping without changing the amplifier gain setting.',['The desired output amplitude equals the input amplitude multiplied by gain magnitude.','A sufficiently smaller input keeps the whole output waveform within the output limits.']);
  add(12,'feedback','Negative feedback','Describe negative feedback in a voltage amplifier.',['A portion of the output is returned so that it opposes the differential input signal.','The output is adjusted to reduce the error between the input-related signals.'],'Explain why negative feedback makes amplifier gain less dependent on the exact open-loop gain.',['With sufficiently large open-loop gain, the feedback network primarily sets the closed-loop gain.','Variations in open-loop gain produce a smaller fractional change in the closed-loop gain.']);
  add(12,'comparator','Comparators','Describe the action of an op-amp used as a comparator without negative feedback.',['The output goes to a high or low limiting value according to the sign of the input voltage difference.','It compares a signal with a reference voltage rather than producing a proportional linear output.'],'Explain why a slowly varying noisy input can cause repeated comparator switching near the reference voltage.',['Noise repeatedly changes the sign of the small input difference.','The large open-loop gain drives the output alternately towards its limiting states.']);
  add(12,'adc','Analogue-to-digital conversion','Describe the purpose of an analogue-to-digital converter.',['It samples an analogue voltage.','It represents the sample using a finite binary code.'],'Explain why increasing the number of bits reduces quantisation uncertainty for the same input range.',['More bits provide more distinct output codes.','The voltage interval assigned to each code becomes smaller, reducing the rounding range.']);
  add(12,'bandwidth','Amplifier bandwidth','State what is meant by the bandwidth of a low-pass amplifier.',['It is the frequency range from the low-frequency region up to its specified upper cutoff.','The cutoff is commonly where voltage gain has fallen to 1/square root of 2 of its low-frequency value.'],'Explain the gain-bandwidth tradeoff for an op-amp with an approximately constant gain-bandwidth product.',['Closed-loop gain multiplied by bandwidth is approximately constant within the model.','Increasing the selected gain reduces the bandwidth available for undistorted amplification of higher frequencies.']);
  add(13,'repeats','Repeating measurements','State why repeat measurements are useful in an experiment.',['They reveal the scatter and can help identify inconsistent measurements.','A mean of independent repeats reduces the effect of random fluctuations.'],'Explain why repeats do not replace calibration checks.',['A calibration error can shift every reading in the same direction.','Repeating with the same biased instrument retains the systematic error.']);
  add(13,'controls','Control variables','Explain what a control variable is in an experiment.',['It is a quantity kept constant while the independent variable is changed.','Controlling it helps isolate the effect being investigated.'],'In a resistance-against-length investigation, explain why wire material, area and temperature should be controlled.',['Resistance depends on all these quantities as well as length.','Their variation could mimic or obscure the effect of length and invalidate the inferred relationship.']);
  add(13,'oscillations','Pendulum timing method','Describe a method to improve the precision of a pendulum-period measurement using a stopwatch.',['Time many complete oscillations and divide by their number.','Use a fixed reference point and the same direction of crossing to mark each cycle.'],'Explain why timing many oscillations reduces the percentage effect of start-stop reaction uncertainty.',['The absolute reaction-time uncertainty is approximately unchanged.','The total measured interval is larger, so that uncertainty is a smaller fraction of the total.']);
  add(13,'gradient','Choosing graph axes','State which quantities to plot to test T squared = 4 pi squared L/g for a pendulum.',['Plot T squared vertically and length L horizontally.','The predicted gradient is 4 pi squared/g.'],'Explain why a straight line through the origin within uncertainty supports this model without proving it exactly.',['The equation predicts proportionality between T squared and L.','Finite data and uncertainties can be consistent with other nearby relationships, and systematic errors may remain.']);
  add(13,'micrometer','Measuring wire diameter','Describe a reliable micrometer method for measuring wire diameter.',['Check and correct any zero offset and use the ratchet to apply consistent pressure.','Measure at several positions and orientations and calculate a representative mean.'],'Explain why diameter uncertainty is especially important when calculating resistivity from a wire experiment.',['Area is proportional to diameter squared.','Its percentage uncertainty contribution is twice the diameter percentage uncertainty and enters the calculated resistivity.']);
  add(13,'heating','Specific heat capacity method','Describe the measurements needed for an electrical determination of specific heat capacity.',['Measure sample mass and temperature rise.','Measure electrical power and heating time, or voltage, current and time.'],'Explain two ways to reduce unwanted energy transfer in this experiment.',['Insulate the sample and use a lid where appropriate to reduce transfer to the surroundings.','Ensure good heater and thermometer contact so the measured temperature represents the heated sample.']);
  add(13,'counting','Radiation counting','Describe how to obtain a background-corrected radiation count rate.',['Measure the source-plus-background counts and recording time.','Measure background separately, convert both to rates and subtract the background rate.'],'Explain why longer counting times improve the precision of a low count-rate measurement.',['More counts are collected and the absolute statistical uncertainty grows approximately as square root of N.','The fractional uncertainty is about 1/square root of N, so it decreases as the total count increases.']);
  add(13,'iv','Current-voltage investigation','Describe a circuit for investigating the current-voltage characteristic of a component.',['Use a variable supply or suitable control resistor, with an ammeter in series.','Connect a voltmeter across the component and record several paired readings.'],'Explain why readings should be taken promptly or at low currents when a constant-temperature characteristic is intended.',['Electrical power heats the component and can change its resistance.','Limiting heating helps ensure voltage is the intended changed variable rather than temperature as well.']);
  add(13,'fringes','Measuring fringe spacing','Describe a way to reduce percentage uncertainty when measuring double-slit fringe spacing.',['Measure across several fringe intervals between well-defined centres.','Divide by the number of intervals, which is one fewer than the number of consecutive centres counted.'],'Explain why measuring from one edge of a bright fringe to the opposite edge of another can bias the spacing.',['Bright fringes have finite width and boundaries may be indistinct.','Using inconsistent reference positions adds part of a fringe width to the required centre-to-centre distance.']);
  add(13,'evaluation','Evaluating a practical model','Distinguish a conclusion supported by data from an assumption used to analyse the data.',['A supported conclusion follows from the observations within their uncertainties.','An assumption is a condition taken as valid to apply the model, which may need separate justification.'],'Explain how systematic residuals around a best-fit line can guide evaluation of a model.',['A repeated curved pattern rather than random scatter suggests that a straight-line model may be incomplete.','Investigate alternative dependencies or systematic effects before attributing the pattern only to random uncertainty.']);
  // Interleave response types within each topic without changing any persisted ID.
  const original = QUESTIONS.filter(q => /^q\d+$/.test(q.id));
  const calculations = TOPICS.map((_,topic) => QUESTIONS.filter(q => q.topic === topic && q.id.startsWith('calc-')));
  const explanations = TOPICS.map((_,topic) => QUESTIONS.filter(q => q.topic === topic && q.id.startsWith('explain-')));
  const ordered = [...original];
  const rounds = Math.max(...calculations.map(items => items.length), ...explanations.map(items => 2*items.length));
  for (let i = 0; i < rounds; i++) {
    for (let topic = 0; topic < TOPICS.length; topic++) {
      if (calculations[topic][i]) ordered.push(calculations[topic][i]);
      const explanation = explanations[topic][Math.floor(i/2)];
      if (i % 2 === 1 && explanation) ordered.push(explanation);
    }
  }
  QUESTIONS.splice(0, QUESTIONS.length, ...ordered);
})();
